import { forbidden, unauthorized } from 'next/navigation'
import { verifyAdmin } from '@/app/lib/auth'

// The authorization decision must be made per request, never captured in a
// build-time prerender.
export const dynamic = 'force-dynamic'

export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin()

  // No session at all -> 401, renders app/unauthorized.tsx
  if (!session) {
    unauthorized()
  }

  // Signed in, but lacking the admin role -> 403, renders app/forbidden.tsx
  if (!isAdmin) {
    forbidden()
  }

  return (
    <main>
      <h1>Admin Dashboard</h1>
      <p>
        Signed in as {session.name} ({session.role}).
      </p>
    </main>
  )
}

